public class ReportGenerator {
    public String generateInvoiceLine(String item, int quantity, double price) {
        // Java 15+ formatted() - cleaner syntax
        return "%-20s  Qty: %3d  Price: $%6.2f  Total: $%7.2f"
            .formatted(item, quantity, price, quantity * price);
    }

    public String generateSummary(String username, int orders, double total) {
        // Pre-Java 15 String.format()
        return String.format(
            "Customer: %s%nTotal Orders: %d%nAmount: $%.2f",
            username, orders, total
        );
    }

    public String formatPercentage(double value) {
        return "%.1f%%".formatted(value * 100);  // 0.873 -> "87.3%"
    }

    public String padAccountNumber(int accountNum) {
        return "Account: %08d".formatted(accountNum);  // 1234 -> "Account: 00001234"
    }
}

