public class TextCleaner {
    public String normalizeFilePath(String path) {
        // Use replace() for literal character swap - safe and clear
        return path.replace('\\', '/');
    }

    public String sanitizeFilename(String filename) {
        // WRONG: replaceAll(".", "_") would replace every character
        // var wrong = filename.replaceAll(".", "_");

        // Correct: replace() treats dot literally
        return filename.replace('.', '_');
    }

    public String collapseWhitespace(String text) {
        // Use replaceAll() when you need regex - multiple spaces to single space
        return text.replaceAll("\\s+", " ");
    }

    public String removeNonAlphanumeric(String text) {
        // Regex character class - replaceAll is the right tool
        return text.replaceAll("[^a-zA-Z0-9]", "");
    }

    public String replaceFirstOccurrence(String text, String target) {
        // replaceFirst() for single substitution
        return text.replaceFirst(java.util.regex.Pattern.quote(target), "REPLACED");
    }
}
